package com.kidsvideo.app;
import android.app.UiModeManager;import android.content.Context;import android.content.res.Configuration;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.view.View;import android.widget.TextView;
public final class Ui {private Ui(){} public static int dp(Context c,int dp){return Math.round(dp*c.getResources().getDisplayMetrics().density);} public static boolean isTv(Context c){UiModeManager ui=(UiModeManager)c.getSystemService(Context.UI_MODE_SERVICE);return c.getPackageManager().hasSystemFeature("android.software.leanback")||(ui!=null&&ui.getCurrentModeType()==Configuration.UI_MODE_TYPE_TELEVISION);} public static GradientDrawable rounded(int color,float radiusDp,Context c){GradientDrawable g=new GradientDrawable();g.setColor(color);g.setCornerRadius(dp(c,(int)radiusDp));return g;} public static void styleButton(TextView v,boolean selected){int fill=selected?Color.rgb(255,59,48):Color.rgb(42,42,42);v.setTextColor(Color.WHITE);v.setBackground(rounded(fill,18,v.getContext()));v.setPadding(dp(v.getContext(),16),Ui.dp(v.getContext(),9),Ui.dp(v.getContext(),16),Ui.dp(v.getContext(),9));} public static void focusScale(View v,boolean focused){v.setScaleX(focused?1.04f:1f);v.setScaleY(focused?1.04f:1f);v.setElevation(focused?dp(v.getContext(),8):0);v.setAlpha(focused?1f:0.96f);} }
